import {frontierFloorPlan541} from './frontier-authoring-541.js?v=5.41';
import {FRONTIER_BESTIARY,ITEMS} from './repertoire.js?v=5.38';
// 240 deterministic four-stage commissions. No main-story bits are borrowed.
export const REGIONS=[
 ['dunes','Amber Dunes',2,0,2,4,'#9b7849','sand','Wind-carved ridges, buried aqueducts and amber beetle tracks.','Follow the sheltered side of the ridge.'],
 ['salt','Saltglass Flats',3,3,3,7,'#7b969c','salt','White salt plates surround shallow turquoise brine.','Close the inland gate before opening the sea gate.'],
 ['cactus','Cactus Barrens',4,0,1,4,'#637c49','cactus','Tall barrel cacti shelter the old caravan water stops.','Harvest fallen pads; leave the flowering stems.'],
 ['caldera','Ember Caldera',6,2,6,3,'#754b40','lava','Black basalt shelves divide cooling lava channels.','Vent pressure before cooling the pipe.'],
 ['coral','Coral Shoals',7,1,7,3,'#468a8e','coral','Walkable tidal shelves wind between coral pools.','Cross when the third tide marker is uncovered.'],
 ['mangrove','Mangrove Delta',8,1,1,7,'#3d6858','mangrove','Raised root paths cross brackish water and reed beds.','Open both side channels before the central sluice.'],
 ['crystal','Crystal Caverns',10,2,2,3,'#675582','crystal','Amethyst chambers carry light through mineral seams.','Turn the dull facet toward the light.'],
 ['glacier','Glacier Reach',12,3,3,3,'#769ca7','ice','Blue ice shelves hold abandoned survey cairns.','Anchor the rope before testing the bridge.'],
 ['aurora','Aurora Tundra',14,3,3,4,'#6e829d','aurora','Lichen meadows glow beneath curtains of northern light.','Match the green signal before the violet signal.'],
 ['spore','Sporewood',16,0,1,4,'#526955','spore','Fungal groves grow around fallen rain collectors.','Brush spores downwind of the drinking well.'],
 ['storm','Storm Peaks',18,3,3,3,'#596984','storm','Copper cairns ground the lightning above a broken observatory.','Ground the mast before raising the vane.'],
 ['marble','Marble Wastes',20,2,2,4,'#8c8581','marble','Weathered statues overlook cracked white terraces.','Support the lintel before moving the broken column.']
].map(([id,name,chapter,theme,ground,border,color,style,description,rule])=>({id,name,chapter,theme,ground,border,color,style,description,rule}));
const areas=['Trailhead','Crossing','Hollow','Heights','Sanctuary'];
const jobs=[['Restore the water gauge','Waterkeepers','The settlement cannot tell safe water from a rising flood.','The gauge now gives families time to reach higher ground.'],['Recover the trail record','Surveyors','A missing survey record leaves the next caravan without a safe route.','The corrected route has been copied for every caravan.'],['Reopen the relief station','Relief crew','Travellers have supplies but nowhere safe to unpack them.','The relief crew can open a shelter for the next arrivals.'],['Protect the seed exchange','Seedkeepers','A damaged exchange threatens the next planting season.','The seedkeepers share viable seed with three neighbouring settlements.']];
export const SIDE_CAMPAIGNS=REGIONS.flatMap((r,ri)=>areas.flatMap((area,ai)=>jobs.map(([task,patron,problem,outcome],ji)=>{const n=ri*20+ai*4+ji;return{id:'commission-'+n,number:n+1,region:r.id,regionIndex:ri,area:ai,chapter:r.chapter,title:r.name+' · '+area+': '+task,patron,problem,outcome,rule:r.rule,answer:(ri+ai+ji)%3,species:[FRONTIER_BESTIARY[(ri*2+ai+ji)%FRONTIER_BESTIARY.length].id,FRONTIER_BESTIARY[(24+ri*6+ai+ji)%FRONTIER_BESTIARY.length].id],reward:50+r.chapter*12+ai*8,item:ITEMS[3+(n%(ITEMS.length-3))].id};})));
export function frontierState(w){return w.state.frontiers??={version:1,active:null,stages:{},claimed:[],visited:[]};}
export function frontierStage(w,id){return frontierState(w).stages[id]||0;}
const location=(ri,ai)=>2000+ri*5+ai;
export function floorPlan(ri,ai){return frontierFloorPlan541(ri,ai);}

export function expandFrontiers(data){if(data.frontiersVersion)return data;data.frontiersVersion=1;
 const hub=data.scenes.find(s=>s.location===226)||data.scenes.find(s=>s.key==='town');
 if(hub){const cells=[];for(let y=1;y<hub.height-1;y++)for(let x=1;x<hub.width-1;x++)if(hub.floor[y][x]==='.'&&!hub.objects.some(o=>o.xy&&Math.hypot(x-o.xy[0],y-o.xy[1])<2.2)&&!hub.doors.some(o=>Math.hypot(x-o.xy[0],y-o.xy[1])<2.2))cells.push([x,y]);cells.sort((a,b)=>Math.hypot(a[0]-hub.arrive[0],a[1]-hub.arrive[1])-Math.hypot(b[0]-hub.arrive[0],b[1]-hub.arrive[1]));if(!cells.length)throw Error('No dispatch ledger site');hub.objects.push({type:'frontier-board',xy:cells[0],label:'Frontier dispatch · 240 campaigns'});}
 REGIONS.forEach((r,ri)=>areas.forEach((area,ai)=>{const key='frontier_'+r.id+'_'+ai,objects=[{type:'frontier-board',xy:[6,22],label:'Dispatch ledger · '+area},{type:'frontier-landmark',xy:[10,8],label:'Survey marker',frontierStep:0},{type:'frontier-landmark',xy:[24,7],label:'Field apparatus',frontierStep:1},{type:'camp',xy:[8,23],label:'Frontier shelter'}];objects.push({type:'portal',xy:[4,23],to:'hub',label:'Return to the Commons'});if(ai>0)objects.push({type:'portal',xy:[4,13],to:'frontier_'+r.id+'_'+(ai-1),arrive:[28,13],travel_label:areas[ai-1]});if(ai<4)objects.push({type:'portal',xy:[29,13],to:'frontier_'+r.id+'_'+(ai+1),arrive:[5,13],travel_label:areas[ai+1]});data.scenes.push({...floorPlan(ri,ai),key,location:location(ri,ai),chapter:r.chapter,theme:r.theme,biome:r,title:r.name+' · '+area,song:data.campaign.missions[r.chapter-1].field_song,arrive:[4,23],doors:[],objects});}));return data;}
export function frontierObjects(w){const st=frontierState(w),c=SIDE_CAMPAIGNS.find(c=>c.id===st.active);if(!c||w.scene.location!==location(c.regionIndex,c.area)||frontierStage(w,c.id)!==2)return[];return[{type:'patrol',frontierId:c.id,frontierSpecies:c.species,flag_address:0x920000+c.number,bit:0,enemies:[[0,[25,20]],[1,[27,20]]],text:c.patron+': Keep the marked worksite safe. Watch the creatures’ attack warnings.',win_text:'The worksite is safe. Return to the dispatch ledger to finish the commission.'}];}
export function frontierVisible(w,o){if(o.type!=='frontier-landmark')return true;const s=frontierState(w),c=SIDE_CAMPAIGNS.find(c=>c.id===s.active);return !!c&&w.scene.location===location(c.regionIndex,c.area)&&frontierStage(w,c.id)===o.frontierStep;}
export function frontierBoard(w,page=0){const s=frontierState(w),active=SIDE_CAMPAIGNS.find(c=>c.id===s.active),opts=[];if(active)opts.push(['Current: '+active.title,()=>commission(w,active)]);for(const r of REGIONS.slice(page*4,page*4+4))opts.push([r.name+' · '+(w.state.chapter<r.chapter?'chapter '+r.chapter:s.claimed.filter(id=>SIDE_CAMPAIGNS.find(c=>c.id===id)?.region===r.id).length+'/20 complete'),()=>{if(w.state.chapter<r.chapter&&!w.state.complete)return w.text('This road opens in chapter '+r.chapter+'. Your main journey is unchanged.');regionBoard(w,r);}]);if(page>0)opts.push(['Previous regions',()=>frontierBoard(w,page-1)]);if(page<2)opts.push(['More regions',()=>frontierBoard(w,page+1)]);opts.push(['Leave',()=>{}]);w.choose('FRONTIER DISPATCH\n'+s.claimed.length+'/240 commissions complete. Each has a survey, field repair, encounter and final report. '+(active?'Your active job is saved.':'Choose a region.'),opts);}
function regionBoard(w,r,page=0){const s=frontierState(w),list=SIDE_CAMPAIGNS.filter(c=>c.region===r.id),opts=list.slice(page*4,page*4+4).map(c=>[(s.claimed.includes(c.id)?'✓ ':s.active===c.id?'→ ':'')+c.title.split(': ')[1]+' · '+areas[c.area],()=>commission(w,c)]);if(page>0)opts.push(['Previous jobs',()=>regionBoard(w,r,page-1)]);if(page<4)opts.push(['More jobs',()=>regionBoard(w,r,page+1)]);opts.push(['All regions',()=>frontierBoard(w)]);w.choose(r.name+'\n'+r.description+'\nArea '+(page+1)+'/5 · '+areas[page],opts);}
export function commission(w,c){const s=frontierState(w),stage=frontierStage(w,c.id);if(s.claimed.includes(c.id))return w.text(c.title+'\n'+c.outcome+'\nReward already collected.');const steps=['Read the survey marker.','Repair the field apparatus using the survey clue.','Protect the marked worksite.','Return your report and collect the reward.'];const opts=[];if(stage===3)opts.push(['Submit report · '+c.reward+' credits + '+ITEMS.find(i=>i.id===c.item).name,()=>{if(s.claimed.includes(c.id))return;s.claimed.push(c.id);s.stages[c.id]=4;if(s.active===c.id)s.active=null;w.state.gold+=c.reward;w.state.items[c.item]=(w.state.items[c.item]||0)+1;w.text(c.outcome+'\nCommission complete. The reward has been packed.');}]);else opts.push([s.active===c.id?'Travel to the worksite':'Take this commission and travel',()=>{s.active=c.id;w.loadScene(location(c.regionIndex,c.area));}]);opts.push(['Back to region',()=>regionBoard(w,REGIONS[c.regionIndex])]);w.choose(c.title+'\n'+c.patron+': '+c.problem+(stage>0?'\nSurvey note: '+c.rule:'')+'\nNext: '+steps[Math.min(stage,3)]+'\nReward: '+c.reward+' credits and '+ITEMS.find(i=>i.id===c.item).name+'.',opts);}
export function frontierInteraction(w,o){if(o.type==='frontier-board'){frontierBoard(w);return true;}if(o.type!=='frontier-landmark')return false;const s=frontierState(w),c=SIDE_CAMPAIGNS.find(c=>c.id===s.active);if(!c)return true;if(o.frontierStep===0){s.stages[c.id]=1;w.text([c.patron+': '+c.problem,'FIELD NOTE\n'+c.rule+'\nNow examine the field apparatus. The clue remains available in the dispatch report.']);return true;}const options=['Force the mechanism while it is under load.','Seal every outlet and raise the pressure.','Ignore the survey and remove the supports.'];options[c.answer]=c.rule;w.choose('Repair the apparatus.\nSurvey note: '+c.rule,options.map((label,i)=>[label,()=>{if(i!==c.answer)return w.text('The apparatus resists. No supplies were spent. Check the survey note.');s.stages[c.id]=2;w.text('The apparatus works again. Creatures have gathered at the marked worksite; protect the crew before returning your report.');}]));return true;}
export function frontierVictory(w,o){if(!o.frontierId)return false;frontierState(w).stages[o.frontierId]=Math.max(3,frontierStage(w,o.frontierId));w.text(o.win_text);return true;}
